import { ROLES, validateEmail, validateName, validateRole } from '../validation/userFields.js';

export function updateUser(store, request) {
  const user = store.getUser(Number(request.params.id));
  if (!user) {
    return notFound('user not found');
  }

  const body = request.body ?? {};
  const messages = [];
  const changes = {};

  // Only fields that were sent are validated and applied.
  if (body.email !== undefined) {
    const email = validateEmail(body.email);
    if (email.error) messages.push(email.error);
    else changes.email = email.value;
  }

  if (body.name !== undefined) {
    const name = validateName(body.name, { required: true });
    if (name.error) messages.push(name.error);
    else changes.name = name.value;
  }

  if (body.role !== undefined) {
    const role = validateRole(body.role, { allowed: ROLES });
    if (role.error) messages.push(role.error);
    else changes.role = role.value;
  }

  if (messages.length > 0) {
    return validationFailed(messages);
  }
  if (Object.keys(changes).length === 0) {
    return validationFailed(['no fields to update']);
  }

  const owner = changes.email && store.findUserByEmail(changes.email);
  if (owner && owner.id !== user.id) {
    return conflict('email already in use');
  }
  return ok(store.updateUser(user.id, changes));
}

